import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../providers/app_state.dart';
class WaterTrackerScreen extends ConsumerWidget{const WaterTrackerScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final w=ref.watch(waterProvider);return Scaffold(appBar:AppBar(title:const Text('Water Tracker')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text('${w.glasses}/${w.goal} glasses',style:Theme.of(c).textTheme.displaySmall),const SizedBox(height:16),LinearProgressIndicator(value:w.progress.clamp(0,1),minHeight:14),const SizedBox(height:24),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>ref.read(waterProvider.notifier).remove(),child:const Text('- One glass'))),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:()=>ref.read(waterProvider.notifier).add(),child:const Text('+ One glass')))]),TextButton(onPressed:()=>ref.read(waterProvider.notifier).reset(),child:const Text('Reset today'))])));}}
